Section HCW.
  Context {HCEIL : HeapCeil}.

Definition dof_W (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition dof_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' c' E' g',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (dof_W lo sp P E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells c' pad7 pad2) /\ dof_core c c'
    /\ rw_cells rsegs m' E (ErrCodeCells E') /\ dof_out E'
    /\ bytes_at rsegs m' vp vbs
    /\ HttpCat m' g' /\ XStatics m'.

(* [comment removed for export] *)
Definition dof_pure (sp : word) (P E lo : Z) (c : pcore) (fld vp : Z) (vbs : list byte) : Prop :=
  pcore_ok c /\ 0 <= fld < 2^31 /\ lo + 400 <= bv_unsigned sp /\ 0xb4000 <= lo
  /\ ((0 < vp /\ vp + Z.of_nat (length vbs) <= 0x10000) \/ 0x90d70 <= vp) /\ (vp + Z.of_nat (length vbs) <= lo
                      \/ (bv_unsigned sp <= vp /\ (vp + Z.of_nat (length vbs) <= P \/ P + 80 <= vp) /\ (vp + Z.of_nat (length vbs) <= E \/ E + 24 <= vp)
                          /\ vp + Z.of_nat (length vbs) < 2^64))
  /\ bv_unsigned sp <= P /\ P + 80 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64 /\ (P + 80 <= E \/ E + 24 <= P).

Definition dof_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (fld vp : Z) (vbs : list byte)
    (e1 e2 e3 : word) (g : bool),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells rsegs m E [C8 e1; C8 e2; C8 e3] ->
  bytes_at rsegs m vp vbs ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) ->
  dof_pure sp P E lo c fld vp vbs ->
  mem_inv rsegs m ->
  evt rsegs (dof_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz fld) (wz vp) (wz (Z.of_nat (length vbs))) (wz E) a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_DO_FIELD) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition dof_ctx (m m1 : mem) (sp : word) (sv : list word) (P E lo : Z) (c1 : pcore) (pad7 pad2 : list byte)
    (vp : Z) (vbs : list byte) (e1 e2 e3 : word) (g : bool) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -72) (map C8 sv)
  /\ rw_cells rsegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells rsegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at rsegs m1 vp vbs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -288)
  /\ munch (dof_W lo sp P E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition dof_sv (s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list word := [s7; s6; s5; s4; s3; s2; s1; s0; ra].

Local Ltac dof_finish c' E' g' :=
  apply evt_done; unfold dof_post;
  do 16 eexists; exists c', E', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try assumption; try lia.

Lemma dof_fail_exit : forall e loc,
  In e [HE_BAD_VALUE; HE_BAD_CONTENT_LENGTH; HE_BAD_TRANSFER_ENCODING; HE_MULTIPLE_CONTENT_LENGTH] ->
  Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 -> dof_out (EC_http_loc e loc).
