(* [comment removed for export] *)
Definition dof_exitB_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j1 junk : list byte) (e1 e2 e3 : word) (g : bool),
  dof_ctx m m1 sp (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P E lo c1 pad7 pad2 vp vbs e1 e2 e3 g ->
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 192 j1] ->
  rw_cells rsegs m1 (bv_unsigned sp + -96) [CB 24 junk] ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> dof_core c c1 ->
  In e [HE_BAD_VALUE; HE_BAD_CONTENT_LENGTH; HE_BAD_TRANSFER_ENCODING; HE_MULTIPLE_CONTENT_LENGTH] ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

Local Ltac dof_exitB_script e loc :=
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo c c1 pad7 pad2 vp vbs j1 junk e1 e2 e3 g;
  intros CTX FR1 TMP PURE DC HE;
  pose proof PURE as PURE0;
  destruct CTX as (FRhi & PC & EC & WIN & HC & XS & ST & MU & WM & MI);
