Definition dof_arm_stmt (pc : Z) (P_of_fld : Z -> Prop) : Prop :=
  forall (fld : Z) rax ra sp gp tp t0 t1 t2 a0x a4x a5 a6 a7 s2x s3x s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (fr : list byte) (e1 e2 e3 : word) (g : bool),
  P_of_fld fld ->
  dof_ctx m m1 sp (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 vp vbs e1 e2 e3 g ->
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 216 fr] ->
  dof_pure sp P E lo c fld vp vbs ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0x (wz fld) (wz vp) (wz (Z.of_nat (length vbs))) a4x a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

